prompt.presence.tool.update_presence.sch:
{
		"type": "object",
		"properties": {
			"location": {"type": "string", "description": "where you are, e.g. \"at the edge of the bed\" (max 60 characters)"},
			"attire": {"type": "string", "description": "what you are wearing, e.g. \"a nightdress, coat over the back of the chair\" (max 120 characters)"},
			"posture": {"type": "string", "description": "posture and relative position, e.g. \"sitting against the headboard, blanket over your legs\" (max 120 characters)"},
			"activity": {"type": "string", "description": "what you are doing, e.g. \"leafing through a book you never finished\" (max 120 characters)"},
			"effects": {"type": "string", "description": "anything still in effect, e.g. \"only the bedside lamp is on; the window is open a crack\" (max 200 characters)"},
			"focus": {"type": "string", "description": "what your attention is on, e.g. \"a sound at the door\" (max 80 characters)"}
		}
	}

prompt.read_file.tool.read_file.schema:
{
		"type": "object",
		"properties": {
			"path": {"type": "string", "description": "path of the file to read (absolute or relative)"}
		},
		"required": ["path"]
	}

prompt.scene.tool.list_scenes.schema:
{
		"type": "object",
		"properties": {
			"keyword": {"type": "string", "description": "filter keyword, matched against name and description; leave empty for no filter"}
		}
	}

prompt.scene.tool.save_scene.schema:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "name of the place, short and unique"},
			"detail": {"type": "string", "description": "description of the place: where it is, how it relates to other places, the layout, what is in it, the atmosphere and anything distinctive"},
			"mode": {"type": "string", "description": "what to do when a place of that name already exists; refuses by default", "enum": ["create", "replace"]}
		},
		"required": ["name", "detail"]
	}
